SELECT NTE_DET.ID AS ID_NOTAS_EXPLICATIVAS_DET, NTE_IMG.URL_IMAGEM FROM NOTAS_EXPLICATIVAS_CAB NTE INNER JOIN NOTAS_EXPLICATIVAS_DET NTE_DET ON NTE.ID = NTE_DET.ID_NOTAS_EXPLICATIVAS_CAB INNER JOIN NOTAS_EXPLICATIVAS_IMAGENS NTE_IMG ON NTE_DET.ID = NTE_IMG.ID_NOTAS_EXPLICATIVAS_DET WHERE NTE.CODEMP = :VAR_EMPRESA_DRE AND NTE.REFERENCIA <= :VAR_DATA_REF_DRE ORDER BY NTE_IMG.DT_CRIACAO